<script setup lang="ts">
import ApiPagination from '@/components/common/ApiPagination.vue'
import LoadingRegion from '@/components/common/LoadingRegion.vue'
import { localizePageMessage } from '@/lang/page-message'
import { computed } from 'vue'

import { useI18n } from 'vue-i18n'
const { t, locale } = useI18n()
import { ref, reactive, onMounted } from 'vue'
import { workbench, type Row } from '@/api/workbench'
import { useWorkbench } from '../shared/useWorkbench'
import '../shared/legacy.css'
const { can, loading, error, run } = useWorkbench('warehouse')
const labels = computed<Row>(() => ({ pending_inspection: t('pages.pendingInspection'), ready_to_ship: t('pages.readyToShip'), exchange_in_progress: t('pages.exchanging'), return_in_progress: t('pages.returning'), customer_confirm_pending: t('pages.awaitingCustomerConfirmation'), partially_shipped: t('pages.partiallyShipped'), shipped: t('pages.shipped') }))
const filters = reactive({ scope: 'recent', keyword: '', status: '', page: 1, per_page: 20 }); const data = ref<Row>({ list: [], total: 0, statuses: {}, allTotal: 0 }); const editing = ref<Row | null>(null)
function load() { if (can('list')) run(() => workbench.get('/warehouse', filters), result => { data.value = result; filters.page = result.page }) }
function search() { filters.page = 1; load() }
function edit(row: Row) { editing.value = { ...row, notes: '', items: row.items.map((i: Row) => ({ inspection: 'pending', shippedQuantity: 0, outboundTracking: '', notes: '', ...i })) } }
async function save() { const row = editing.value!; await run(() => workbench.post(`/warehouse/${row.id}/actions`, { version: row.version, status: row.status, notes: row.notes, items: row.items }), () => editing.value = null); if (!error.value) load() }
onMounted(load)
</script>
<template><main class="legacy-workbench"><header><div><h1>{{ t('pages.warehouseWorkbench') }}</h1><p class="muted">{{ t('pages.receiveProcurementHandoffsAndRecordInspectionsCustomerConfirmationsAnd') }}</p></div><div class="toolbar"><a class="link-button" href="https://www.saveb-photos.com/admin" target="_blank" rel="noopener noreferrer">{{ t('pages.openInspectionPhotoSystem') }}</a><button @click="load">{{ t('pages.refresh') }}</button></div></header><p v-if="error" class="error" role="alert">{{ localizePageMessage(error) }}</p><div class="toolbar"><button :class="{ primary: filters.scope === 'recent' }" @click="filters.scope = 'recent'; search()">{{ t('pages.last120Days') }}</button><button :class="{ primary: filters.scope === 'history' }" @click="filters.scope = 'history'; search()">{{ t('pages.historicalOrders') }}</button><button :class="{ primary: filters.scope === 'all' }" @click="filters.scope = 'all'; search()">{{ t('pages.all') }}</button></div><div class="cards"><button class="card" @click="filters.status = ''; search()">{{ t('pages.warehouseOrders') }}<b>{{ data.allTotal }}</b></button><button v-for="(label, status) in labels" :key="status" class="card" :class="{ active: filters.status === status }" @click="filters.status = status; search()">{{ label }}<b>{{ data.statuses[status] || 0 }}</b></button></div><section class="panel"><form class="toolbar" @submit.prevent="search"><label>{{ t('pages.orderCustomerProductTracking') }}<input v-model="filters.keyword" type="search" /></label><label>{{ t('pages.warehouseStatus') }}<select v-model="filters.status"><option value="">{{ t('pages.all') }}</option><option v-for="(label, status) in labels" :key="status" :value="status">{{ label }}</option></select></label><button class="primary" :disabled="loading">{{ t('pages.search2') }}</button></form><LoadingRegion :loading="loading"><div class="table-wrap"><table><thead><tr><th>{{ t('pages.dateOrdered2') }}</th><th>{{ t('pages.orderNumber') }}</th><th>{{ t('pages.customer') }}</th><th>{{ t('pages.item') }}</th><th>{{ t('pages.supplier') }}</th><th>{{ t('pages.inboundTracking') }}</th><th>{{ t('pages.warehouseStatus') }}</th><th>{{ t('pages.action') }}</th></tr></thead><tbody><tr v-for="row in data.list" :key="row.id"><td>{{ row.date }}</td><td>{{ row.orderId }}</td><td>{{ row.customer }}</td><td>{{ row.productName }}</td><td>{{ row.supplier }}</td><td>{{ row.trackingNumber }}</td><td><span class="badge">{{ labels[row.status] }}</span></td><td><button v-if="can('update')" @click="edit(row)">{{ t('pages.inspectShip') }}</button></td></tr></tbody></table><p v-if="!data.list.length" class="empty">{{ loading ? t('pages.loading2') : t('pages.noWarehouseRecordsProcurementTasksAppearHereOnceSaved') }}</p></div><ApiPagination v-model:page="filters.page" v-model:size="filters.per_page" :total="data.total" :loading="loading" @change="load" /></LoadingRegion></section><div v-if="editing" class="editor" role="dialog" aria-modal="true" :aria-label="t('pages.warehouseProcessing')"><form class="editor-content" @submit.prevent="save"><header><h2>{{ t('pages.warehouseProcessing2', { p0: (editing.orderId) }) }}</h2><button type="button" @click="editing = null">{{ t('pages.close') }}</button></header><p v-if="error" class="error">{{ localizePageMessage(error) }}</p><label>{{ t('pages.currentStage') }}<select v-model="editing.status"><option v-for="(label, status) in labels" :key="status" :value="status">{{ label }}</option></select></label><section v-for="(item, index) in editing.items" :key="index" class="panel" style="margin-top:16px"><h3>{{ t('pages.purchasedQuantity', { p0: (item.name || editing.productName), p1: (item.quantity) }) }}</h3><div class="form-grid"><label>{{ t('pages.inspectionResult') }}<select v-model="item.inspection"><option value="pending">{{ t('pages.pendingInspection') }}</option><option value="passed">{{ t('pages.passed') }}</option><option value="failed">{{ t('pages.failed') }}</option></select></label><label>{{ t('pages.totalShippedQuantity') }}<input v-model.number="item.shippedQuantity" type="number" min="0" :max="item.quantity" required /></label><label>{{ t('pages.outboundTrackingNumber') }}<input v-model="item.outboundTracking" /></label><label>{{ t('pages.itemNotes') }}<input v-model="item.notes" /></label></div></section><label>{{ t('pages.operationNotes') }}<textarea v-model="editing.notes" rows="3" /></label><p class="muted">{{ t('pages.shippedQuantityCannotExceedPurchasedQuantityInspectionMustPass') }}</p><button class="primary" :disabled="loading">{{ t('pages.saveProcessingResults') }}</button><h3 style="margin-top:24px">{{ t('pages.operationHistory') }}</h3><p v-for="(entry, index) in editing.history" :key="index" class="muted">{{ entry.at }} · {{ labels[entry.status] || entry.status }} · {{ entry.notes }}</p></form></div></main></template>
